type Row=Record<string,any>;type Action={key:string;label:string;primary?:boolean};
const modules=[
 {key:'batches',label:'服务与业务批次',createLabel:'配置业务批次',roles:['business','leader','counselor'],description:'固定办理规则、对象与责任节点；规则更新只影响新建事项。'},
 {key:'cases',label:'部门协同',createLabel:'发起协同事项',roles:['student','counselor','business','leader','logistics'],description:'跟踪部门接收、前置条件、补正与收尾，全部必办节点完成后核验办结。'},
 {key:'materials',label:'材料库',createLabel:'提交材料版本',roles:['student'],description:'一次上传，按用途确认复用。更正创建新版本，历史引用保持原样。'},
 {key:'resources',label:'名额与额度',createLabel:'创建资源分配',roles:['business','leader'],description:'校级总量与学院分配分开核算，预占和正式占用同时受名额及金额约束。'},
 {key:'awards',label:'资助与评审',createLabel:'申请资助',roles:['student'],description:'申报、学院评议、预占公示、异议、批准、财务执行与对账分别记录。'},
 {key:'receipts',label:'财务回执核验',createLabel:'导入正式回执',roles:['finance'],description:'每条回执保留发生额、原始事件和来源，双人复核后参与累计。'},
 {key:'beds',label:'床位台账',createLabel:'登记床位',roles:['logistics'],description:'预留、入住与维修分开记录；一床一人，交接确认后释放资源。'},
 {key:'housing',label:'入住调宿退宿',createLabel:'申请住宿办理',roles:['student','counselor','logistics'],description:'先核验目标床位，再确认实际交接。分配失败时原床位保持不变。'},
 {key:'enrollment',label:'迎新与异动',createLabel:'导入招生身份',roles:['business','leader'],description:'核验招生源身份与正式学生唯一关联，异动生成影响清单并保留原记录。'},
 {key:'activities',label:'活动与成果',createLabel:'发布活动',roles:['counselor','business','mentor'],description:'报名名额、候补、实际到场和成果认定分别管理。'},
 {key:'support',label:'学业就业帮扶',createLabel:'建立帮扶事项',roles:['business','counselor'],description:'以核验的权威状态开展联系和帮扶，保留行动、来源及后续跟进。'},
 {key:'events',label:'事件同步核验',createLabel:'登记权威事件',roles:['business','leader','counselor'],description:'已核验的业务事件去重消费；失败显示原因，有限重试后由责任人核验。'},
 {key:'transfers',label:'学院额度转拨',createLabel:'发起转拨复核',roles:['leader'],description:'同一校级项目内双人复核转拨；不能调走已预占或已正式使用的额度。'},
