 {key:'shifts',label:'勤工排班',createLabel:'安排班次',roles:['business'],description:'仅对已确认在岗学生安排班次，跨岗位校验人员时间冲突。'}
];
const visibleModules=computed(()=>modules.filter(m=>!props.user.roleRestricted||(props.user.allowedModules||[]).includes(m.key)).filter(m=>m.key==='events'?['business','leader','counselor'].includes(props.user.role):m.key==='transfers'?props.user.role==='leader':['jobs','shifts'].includes(m.key)?['business','counselor','student'].includes(props.user.role):m.key==='receipts'?props.user.role==='finance':m.key==='beds'?['logistics','student'].includes(props.user.role):m.key==='resources'?['leader','business','admin','sysadmin'].includes(props.user.role):m.key==='enrollment'?['leader','business','counselor','student'].includes(props.user.role):!['admin','sysadmin','assistant'].includes(props.user.role)||m.key==='batches'));
const initialModule = computed(() => visibleModules.value.some(module => module.key === props.initialModule) ? props.initialModule! : '');
const active=ref(initialModule.value||visibleModules.value[0]?.key||'batches'),search=ref(''),statusFilter=ref(''),data=ref<Record<string,Row[]>>({}),loading=ref(false),error=ref(''),saving=ref(false),uploading=ref(false);
const operationsRoot=ref<HTMLElement>();
const activeModule=computed(()=>modules.find(m=>m.key===active.value)!);const canCreate=computed(()=>activeModule.value.roles.includes(props.user.role));
const rows=computed(()=>data.value[active.value]||[]);const statuses=computed(()=>[...new Set(rows.value.map(r=>r.status).filter(Boolean))]);const visibleRows=computed(()=>rows.value.filter(r=>(!statusFilter.value||r.status===statusFilter.value)&&[r.title,r.studentName,r.id,r.eventId].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const roleStudents=ref<Row[]>([]);const staff=computed(()=>props.users.filter(u=>u.enabled!==false&&!['student','admin','sysadmin','assistant'].includes(u.role)));const students=computed(()=>props.user.roleRestricted?roleStudents.value:props.users.filter(u=>u.role==='student'));
const statusMap:Record<string,string>={open:'开放',closed:'已办结',pending:'待接收',pending_identity:'待身份核验',verified:'已核验',submitted:'待审核',returned:'待补正',reviewed:'学院评议完成',waitlisted:'候补',shortlisted:'拟入选已预占',publicity:'公示中',approved:'已批准',handed_off:'已移交财务',cancelling:'撤销收尾中',cancelled:'已撤销',rejected:'已否决',in_progress:'办理中',supplement:'待补充',verification:'待主责核验',paused:'暂停',completed:'已完成',waived:'有效豁免',terminated:'已终止',active:'有效',available:'可用',reserved:'已预留',occupied:'已入住',maintenance:'维修停用',published:'已发布',registered:'正式报名',attended:'已核验到场',recognized:'已认定',none:'未提交',pending_verification:'待到场核验',difference:'差异待核验',discrepancy:'差异待核验',awaiting_handoff:'待移交',awaiting_receipt:'待回执',partial:'部分完成',success:'成功',failed:'失败',reversal:'冲正',stopped:'正式停止执行',confirmed:'复核通过',excluded:'已排除',resolved:'已解决',pending_review:'待部门核验'};
const purposeLabels:Record<string,string>={award:'奖助申请',case:'协同办理'};
function statusLabel(v:string){return ({awaiting_condition:'待核验适用条件',not_applicable:'经核验不适用',applied:'待人工评议',selected:'拟聘名额已预留',employed:'已确认在岗',ended:'在岗已结束',withdrawn:'已退出',scheduled:'已安排',processed:'已同步'} as Record<string,string>)[v]||statusMap[v]||v||'未开始'}
function tagType(v:string){return ['closed','completed','confirmed','recognized','verified'].includes(v)?'success':['rejected','discrepancy','difference'].includes(v)?'danger':['returned','cancelling','pending','supplement'].includes(v)?'warning':'info'}
function formatTime(v:string){return v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'未设置'}function money(v:any){return `¥${(Number(v||0)/100).toFixed(2)}`}
