function resourceName(id:string){return data.value.resources?.find(b=>b.id===id)?.title||id||'无'}function studentName(id:string){return students.value.find(b=>b.id===id)?.name||id}
async function load(){loading.value=true;error.value='';const sessionToken=getToken();try{const keys=[...new Set([active.value,'batches',...(['awards','batches','resources','transfers','jobs'].includes(active.value)?['resources']:[]),...(active.value==='shifts'?['jobs']:[]),...(active.value==='housing'?['beds']:[]),...(['awards','cases'].includes(active.value)?['materials']:[])])];const requests=keys.filter(key=>!props.user.roleRestricted||(props.user.allowedModules||[]).includes(key)).map(async key=>({key,rows:await api<Row[]>(`/erp/${key}`)}));if(props.user.roleRestricted&&['business','leader','logistics'].includes(props.user.role))requests.push(api<Row[]>('/identity/role-students').then(rows=>({key:'roleStudents',rows})));const results=await Promise.all(requests);if(getToken()!==sessionToken)return;for(const result of results)if(result.key==='roleStudents')roleStudents.value=result.rows;else data.value[result.key]=result.rows;await nextTick();focusInitialRecord();}catch(e:any){if(getToken()!==sessionToken)return;error.value=e.message;}finally{if(getToken()===sessionToken)loading.value=false;}}
function changeModule(key:string){active.value=key;statusFilter.value='';search.value='';load()}onMounted(load);
