function focusInitialRecord(){if(!props.initialRecordId||!initialModule.value||active.value!==initialModule.value)return;const id=initialRecordKey(),row=rows.value.find(item=>String(item.id)===id);if(!row){if(!error.value)ElMessage.info('这项业务事项已变化或当前账号无权查看，请刷新列表。');return;}const target=[...(operationsRoot.value?.querySelectorAll<HTMLElement>('[data-erp-record-id]')||[])].find(element=>element.dataset.erpRecordId===id);target?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});}
