const dialog=ref(false),dialogTitle=ref(''),dialogError=ref(''),selected=ref<Row|null>(null),operation=ref('create'),form=ref<Row>({}),fields=ref<any[]>([]),historyRow=ref<Row|null>(null);let operationId='',operationStorageKey='';
