const reason=()=>field('reason','办理说明 / 核验依据','textarea');const attachment=()=>field('attachmentIds','材料附件','attachments',{required:false});const studentField=()=>field('studentId','学生','select',{options:students.value.map(student=>({value:student.id,label:[student.name,student.username,student.className].filter(Boolean).join(' · ')}))});
function reuse(){return[field('materialIds','复用已核验材料','multi',{required:false,options:options((data.value.materials||[]).filter(m=>m.status==='verified'))}),field('confirmMaterialReuse','复用确认','bool',{required:false,hint:'本人确认按本次业务用途向指定办理部门引用所选材料'})]}
function createFields():any[]{
 const title=field('title','名称'),content=field('content','办理内容 / 必要说明','textarea'),source=field('source','授权数据来源'),sourceRef=field('sourceReference','正式来源文件或凭据编号');
 if(active.value==='batches')return[title,field('type','业务类型','select',{options:[['aid','助学资助'],['honor','奖学金荣誉'],['loan','贷款协办'],['tuition','学费减免'],['job','勤工岗位'],['case','跨部门服务'],['enrollment','迎新'],['graduation','毕业离校']].map(([value,label])=>({value,label}))}),field('instructions','办理说明','textarea'),field('contact','办理部门联系方式'),field('qualification','人工核验资格条件','textarea',{required:false}),field('materialRequirements','材料要求','textarea',{required:false}),field('classNames','适用班级（留空为本学院）','multi',{required:false,allowCreate:true,options:[...new Set(students.value.map(s=>s.className))].map(c=>({value:c,label:c}))}),field('opensAt','开放时间','date'),field('closesAt','申请截止','date'),field('ruleBasis','学校批准制度及版本'),field('resourceId','学院资源分配（资助必选）','select',{required:false,options:options((data.value.resources||[]).filter(r=>r.parentId))}),field('allowPartialApproval','分批推进规则','bool',{required:false,hint:'校规允许同批次其他对象仍有异议时推进无异议对象'}),field('slaHours','承诺办理时限（小时）','number'),field('nodes','跨部门责任节点（服务、迎新、离校必填）','nodes',{required:false})];
 if(active.value==='materials')return[title,source,field('purposes','允许用途','multi',{options:[{value:'award',label:'奖助申请'},{value:'case',label:'协同办理'}]}),field('departments','允许接收部门','multi',{options:[{value:'business',label:'业务部门'},{value:'counselor',label:'辅导员'}]}),field('validUntil','有效截止','date'),field('previousId','更正前材料版本','select',{required:false,options:options(data.value.materials||[])}),attachment()];
 if(active.value==='cases')return[field('batchId','服务批次','select',{options:options((data.value.batches||[]).filter(b=>['case','service','enrollment','graduation'].includes(b.type)))}),...(props.user.role==='student'?[]:[studentField()]),title,content,field('publicSummary','跨部门可见的必要摘要','textarea'),field('sensitive','内容分级','bool',{required:false,hint:'含敏感诉求，接收部门只展示必要摘要'}),attachment(),...reuse()];
 if(active.value==='resources')return[title,field('kind','资源类型','select',{options:[{value:'grant',label:'奖助名额与额度'},{value:'workstudy',label:'勤工岗位名额（额度填零）'}]}),field('project','所属项目'),field('year','年度'),field('college','分配学院 / 校级总量标识'),field('parentId','上级总量（校级总量留空）','select',{required:false,options:options((data.value.resources||[]).filter(r=>!r.parentId))}),field('slots','名额总数（人）','number'),field('cents','批准额度（分）','cents'),reason()];
 if(active.value==='awards')return[field('batchId','资助项目批次','select',{options:options((data.value.batches||[]).filter(b=>['aid','honor','loan','tuition','job'].includes(b.type)))}),field('requestedCents','申请金额（分）','cents'),content,attachment(),...reuse()];
 if(active.value==='receipts')return[field('eventId','唯一财务执行事件号'),field('attemptId','执行尝试号'),field('approvalId','批准明细号'),field('voucher','财务凭证号'),field('occurredAt','实际发生时间','date'),field('cents','本次发生额（分）','cents'),field('result','财务结果','select',{options:['success','partial','failed','reversal','stopped'].map(value=>({value,label:statusLabel(value)}))}),field('originalEventId','冲正关联原执行事件号','text',{required:false}),source,sourceRef,reason(),attachment(),field('formalReceipt','来源确认','bool',{hint:'已核实这是正式财务本次发生额回执，并非累计金额或示例'})];
 if(active.value==='beds')return[field('campus','校区'),field('building','楼栋'),field('room','房间'),field('bed','床号'),field('conditions','可用条件 / 适用对象','textarea'),source];
 if(active.value==='housing')return[...(props.user.role==='student'?[]:[studentField()]),field('type','办理类型','select',{options:[{value:'checkin',label:'入住'},{value:'move',label:'调宿'},{value:'checkout',label:'退宿'}]}),content];
 if(active.value==='enrollment')return[field('name','招生姓名'),field('externalId','招生权威源唯一标识'),source,sourceRef,reason()];
 if(active.value==='activities')return[title,content,field('capacity','活动容量（人）','number'),field('registerUntil','报名截止','date'),field('startsAt','活动开始','date'),field('endsAt','活动结束','date')];
 if(active.value==='events')return[field('eventId','权威事件唯一编号'),source,field('type','本地消费方式','select',{options:[{value:'case_progress',label:'按真实节点重新核对协同进度'},{value:'student_impact',label:'生成学生异动影响核验清单'}]}),field('businessId','关联事项 / 学生稳定标识'),field('sourceVerified','权威来源已核验','bool')];
