 if(active.value==='jobs')return[title,content,field('requirements','岗位条件与人工评议要求','textarea'),field('contact','岗位联系人'),field('resourceId','专用勤工岗位名额','select',{options:options((data.value.resources||[]).filter(r=>r.parentId&&r.kind==='workstudy'))}),field('closesAt','申请截止时间','date')];
 if(active.value==='shifts')return[field('jobId','岗位','select',{options:options(data.value.jobs||[])}),studentField(),field('startsAt','班次开始','date'),field('endsAt','班次结束','date'),field('location','工作地点')];
 return[title,studentField(),field('serviceType','服务类型','select',{options:[{value:'academic',label:'学业帮扶'},{value:'employment',label:'就业帮扶'}]}),field('authoritativeStatus','已核验权威服务状态'),source,sourceRef,field('sourceVerified','来源核验','bool'),field('plan','帮扶计划','textarea'),field('dueAt','下次跟进日期','date')];
}
function actions(r:Row):Action[]{const list:Action[]=[];const add=(key:string,label:string,primary=false)=>list.push({key,label,primary});const role=props.user.role,own=r.studentId===props.user.id,owner=r.ownerId===props.user.id,state=r.status;
 if(active.value==='batches' && ['business','leader','counselor'].includes(role)&&owner){add('revise','修订后续批次规则');if(state==='open')add('close','核验关闭批次');}
 if(active.value==='materials' && ['counselor','business'].includes(role)&&state==='pending'){add('verify','核验通过',true);add('reject','退回材料');}
 if(active.value==='resources' && ['business','leader'].includes(role))add('adjust','调整分配');
 if(active.value==='cases'){if(owner){if(state==='closed')add('reopen','重开复核');else if(state==='cancelling')add('finish_cancel','核验撤销收尾',true);else if(state!=='cancelled'){add('close','主责核验办结',true);add('cancel','发起撤销');if(r.feedback?.some((f:Row)=>f.type==='appeal'&&f.status==='open'))add('resolve_appeal','处理申诉');}}if(own&&!['cancelled','cancelling'].includes(state)){add('supplement','补充说明');add('inquire','催询');add('appeal','提出申诉');if(!['closed'].includes(state))add('cancel','申请撤销');}}
 if(active.value==='awards'){if(role==='student'){if(state==='publicity')add('object','提交公示异议');if(own){if(state==='returned')add('resubmit','补正重新提交',true);if(['submitted','returned','reviewed','waitlisted','shortlisted','publicity'].includes(state))add('cancel','退出申请');}}if(role==='counselor'&&state==='submitted'){add('review','学院人工评议通过',true);add('return','退回补正');}if(role==='business'){if(['reviewed','waitlisted'].includes(state)){add('reserve','确认拟入选并预占',true);if(state==='reviewed')add('waitlist','人工登记候补');}if(state==='shortlisted')add('publish','发起公示',true);if(state==='publicity')add('approve','核验并最终批准',true);if(state==='approved')add('handoff','移交财务清单',true);if(state==='handed_off')add('close','对账办结',true);if(state==='cancelling')add('finish_cancel','核验撤销收尾',true);if(['cancelling','closed'].includes(state)&&r.executionId)add('reopen_execution','重开执行复核');if(!['closed','cancelled','rejected','cancelling'].includes(state))add('cancel','取消 / 撤销收尾');}}
 if(active.value==='receipts'&&['pending','discrepancy'].includes(state)&&r.importedBy!==props.user.id){add('confirm','复核并确认',true);add('exclude','核验排除');}
 if(active.value==='beds'&&role==='logistics'){if(state==='available')add('maintenance','停用维修');if(state==='maintenance')add('available','维修后恢复');if(state==='reserved')add('release_reservation','到期核验释放');}
 if(active.value==='housing'){if(role==='logistics'){if(['submitted','returned'].includes(state)){add('approve','核验并安排床位',true);if(state==='submitted')add('reject','不予批准');}if(state==='approved')add('confirm_handover','确认实际交接',true);}if(['submitted','approved','returned'].includes(state))add('cancel','取消办理');}
 if(active.value==='enrollment'&&['business','leader'].includes(role)){if(state==='pending_identity')add('link','核验身份并关联',true);else{if(role==='leader')add('correct_link','纠正身份关联');add('authoritative_change','登记权威异动');}}
 if(active.value==='activities'){if(role==='student'&&state==='published'&&!r.registrations?.some((e:Row)=>e.studentId===props.user.id&&e.status!=='cancelled'))add('register','报名 / 加入候补',true);if(owner&&state!=='cancelled')add('cancel','取消活动');}
 if(active.value==='support'){if(role==='student')add('request_correction','向主管部门申请更正');else if(state!=='closed'){add('followup','记录跟进行动',true);add('close','记录结果并结案');}}
 if(active.value==='cases'&&owner&&r.nodes?.some((n:Row)=>n.status==='awaiting_condition'))add('confirm_conditions','核验模板适用条件',true);
 if(active.value==='events'&&['pending','failed'].includes(state)){add('retry','重新核验并同步',true);add('exclude','核验排除事件');}
 if(active.value==='transfers'&&state==='pending'){if(r.reviewerId===props.user.id){add('approve','复核确认转拨',true);add('reject','复核不通过');}if(owner)add('cancel','撤回转拨申请');}
 if(active.value==='jobs'&&state==='open'){if(role==='student'&&!r.applications?.some((a:Row)=>a.studentId===props.user.id))add('apply','申请岗位',true);if(owner)add('close','核验关闭岗位');}
 if(active.value==='shifts'&&owner&&state==='scheduled'){add('confirm_work','核验实际工作',true);add('cancel','取消班次');}return list;}
function nodeActions(r:Row,n:Row):Action[]{if(['closed','cancelled','cancelling'].includes(r.status))return[];const a:Action[]=[];if(n.pendingOwnerId===props.user.id)a.push({key:'accept_transfer',label:'接收转派'});if(n.ownerId===props.user.id){if(n.status==='pending')a.push({key:'accept',label:'确认接收'});if(n.status==='in_progress')a.push({key:'complete',label:'登记完成'},{key:'return',label:'要求补充'},{key:'pause',label:'暂停'});if(n.status==='paused')a.push({key:'resume',label:'恢复办理'});if(n.status==='supplement')a.push({key:'continue',label:'补正后继续'});if(!['completed','terminated','waived'].includes(n.status))a.push({key:'transfer',label:'转派'},{key:'escalate',label:'提交协调'});}if(props.user.role==='leader'&&!['completed','terminated','waived'].includes(n.status))a.push({key:'waive',label:'授权豁免'});return a;}
function registrationActions(r:Row,e:Row):Action[]{if(r.status==='cancelled')return[];if(r.ownerId===props.user.id){const a:Action[]=[];if(e.status==='registered')a.push({key:'checkin',label:'核验实际到场'});if(e.achievementStatus==='submitted')a.push({key:'recognize',label:'认定成果'},{key:'return_achievement',label:'退回成果'});return a;}if(e.studentId!==props.user.id)return[];if(['registered','waitlisted'].includes(e.status))return[{key:'withdraw',label:'退出报名'},...(e.status==='registered'?[{key:'request_attendance',label:'申请到场核验'}]:[])];if(e.status==='attended')return[...(e.achievementStatus!=='recognized'?[{key:'submit_achievement',label:'提交成果'}]:[]),{key:'evaluate',label:'活动评价'}];return[];}
function jobActions(r:Row,a:Row):Action[]{if(r.ownerId===props.user.id){if(a.status==='applied')return[{key:'select',label:'人工评议并预留名额'},{key:'reject',label:'不予聘任'}];if(a.status==='selected')return[{key:'reject',label:'取消拟聘'}];if(a.status==='employed')return[{key:'end_job',label:'办理在岗结束'}];return[];}if(a.studentId!==props.user.id)return[];if(a.status==='selected')return[{key:'accept_job',label:'确认接受岗位'},{key:'withdraw',label:'退出申请'}];if(a.status==='applied')return[{key:'withdraw',label:'退出申请'}];return[];}
function initialize(list:any[],preset:Row={}){const m:Row={};for(const f of list)m[f.key]=f.type==='multi'||f.type==='nodes'||f.type==='attachments'?[]:f.type==='bool'?false:f.type==='number'||f.type==='cents'?0:'';form.value={...m,...preset};fields.value=list;operationStorageKey=`erp-operation:${props.user.id}:${active.value}:${selected.value?.id||'new'}:${operation.value}:${preset.nodeCode||preset.studentId||preset.objectionId||''}`;operationId=sessionStorage.getItem(operationStorageKey)||Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');sessionStorage.setItem(operationStorageKey,operationId);dialogError.value='';dialog.value=true;}
function openCreate(){operation.value='create';selected.value=null;dialogTitle.value=activeModule.value.createLabel;initialize(createFields(),{slaHours:72});}
function openAction(row:Row,action:Action,node?:Row,extra:Row={}){operation.value=action.key;selected.value=row;dialogTitle.value=action.label;let fs:any[]=[reason()];const key=action.key;
 if(key==='revise'||key==='adjust')fs=[...createFields(),...(key==='revise'?[reason()]:[])];
 if(key==='resubmit')fs=[field('content','补正内容','textarea'),attachment(),...reuse()];
 if(key==='reserve')fs=[field('approvedCents','拟批准金额（分）','cents'),reason()];
 if(key==='publish')fs=[field('publicUntil','公示截止','date'),field('publicSummary','公示必要说明（不含家庭等敏感资料）','textarea'),reason()];
 if(key==='transfer')fs=[field('nextOwnerId','拟转派经办人','select',{options:options(staff.value,'name')}),reason()];
 if(key==='reopen')fs=[field('nodeCode','需要更正的原节点（依赖节点一并重新核验）','select',{options:(row.nodes||[]).map((n:Row)=>({value:n.code,label:n.title}))}),reason()];
 if(key==='waive')fs=[reason(),field('waiverUntil','豁免有效期限','date')];
 if(key==='finish_cancel')fs=[reason(),field('cleanupConfirmed','收尾确认','bool',{hint:'已核验执行停止、资源处理及全部外部结果'})];
 if(key==='close'&&active.value==='cases'&&row.type==='graduation')fs=[reason(),field('borrowedItemsVerified','离校核验','bool',{hint:'物品借用、未结服务和床位交接均已核验；办结后停用学生账号'})];
 if(key==='approve'&&active.value==='housing'&&row.type!=='checkout')fs=[field('targetBedId','目标可用床位','select',{options:options((data.value.beds||[]).filter(b=>b.status==='available'))}),field('reservedUntil','预留有效期','date'),reason()];
 if(key==='confirm_handover')fs=[reason(),field('handoverReference','实际交接凭据编号'),field('actualHandover','现场交接确认','bool',{hint:'实际搬迁或退宿交接已经完成'})];
 if(key==='link'||key==='correct_link')fs=[studentField(),field('identityEvidence','权威身份核验依据'),reason(),field('identityVerified','身份核验','bool',{hint:'已核验招生记录与校内稳定标识，并非仅凭同名关联'})];
 if(key==='authoritative_change')fs=[field('eventId','权威异动事件唯一编号'),field('changeType','异动类型','select',{options:[{value:'transfer',label:'转专业 / 转班'},{value:'suspend',label:'休学'},{value:'resume',label:'复学'}]}),field('sourceReference','权威来源凭据'),field('effectiveAt','生效时间','date'),reason(),field('sourceVerified','权威来源已核验','bool')];
 if(key==='acknowledge_change')fs=[reason(),field('departmentsConfirmed','部门逐项核验确认','bool')];
 if(key==='followup')fs=[reason(),field('dueAt','下一次跟进时间','date')];
 if(key==='submit_achievement')fs=[reason(),attachment()];
 if(key==='confirm_conditions')fs=[...([...new Set((row.nodes||[]).filter((n:Row)=>n.status==='awaiting_condition').map((n:Row)=>n.condition.field))] as string[]).map(name=>field(`fact_${name}`,`核验字段：${name}`,'text',{required:false})),reason()];
 if(key==='confirm_work')fs=[field('actualMinutes','核验实际工作分钟数','number'),reason()];
 if(['register','withdraw','accept','accept_transfer','resume','continue'].includes(key))fs=[];
 initialize(fs,{...(['revise','adjust','resubmit'].includes(key)?row:{}),...extra,nodeCode:node?.code||''});}
async function submit(){if(saving.value||uploading.value)return;for(const f of fields.value){if(f.required===false)continue;const value=form.value[f.key];if(f.type==='bool'?!value:Array.isArray(value)?!value.length:value===''||value==null){dialogError.value=`请填写或确认“${f.label}”`;return;}}saving.value=true;dialogError.value='';try{const previous=props.user.roleRestricted?{found:false}:await api(`/erp/operation-result/${operationId}`);if(previous.found){sessionStorage.removeItem(operationStorageKey);dialog.value=false;ElMessage.success('上次操作已保存，已恢复办理结果，请查看最新记录');await load();return;}const payload:Row={...form.value,action:operation.value,operationId,version:selected.value?.version};if(operation.value==='confirm_conditions'){payload.facts={};for(const key of Object.keys(form.value))if(key.startsWith('fact_'))payload.facts[key.slice(5)]=form.value[key];}const path=operation.value==='create'?`/erp/${active.value}`:`/erp/${active.value}/${selected.value!.id}/action`;await api(path,{method:'POST',body:payload});sessionStorage.removeItem(operationStorageKey);dialog.value=false;ElMessage.success('办理结果已保存');await load();}catch(e:any){dialogError.value=e.message;}finally{saving.value=false;}}
function actionLabel(action:string){return ({create:'创建',review:'学院评议',reserve:'预占资源',approve:'批准',handoff:'移交财务',confirm:'复核确认',close:'核验办结',cancel:'发起撤销',finish_cancel:'撤销收尾',publish:'公示',complete:'节点完成',accept:'接收',transfer:'提出转派',accept_transfer:'接收转派',resubmit:'补正提交',adjust:'调整额度',confirm_handover:'实际交接'} as Record<string,string>)[action]||action;}
function exportCurrent(){const columns=active.value==='resources'?['id','title','college','slots','heldSlots','occupiedSlots','cents','availableCents']:active.value==='receipts'?['eventId','approvalId','attemptId','voucher','occurredAt','cents','result','status','source','sourceReference']:['id','studentId','title','approvalId','executionId','approvedCents','paidCents','executionStatus','status'];const csv='\uFEFF'+[['生成时间',new Date().toISOString()],['用途','当前授权范围业务核对'],columns,...visibleRows.value.map(r=>columns.map(k=>r[k]))].map(row=>row.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${activeModule.value.label}-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
